mapper.select:
SELECT board_no, board_title, board_content, board_reg_date, board_view_cnt FROM board
WHERE ${key} LIKE concat('%',#{word},'%')
ORDER BY ${orderBy} ${orderByDir}

mapper.update:
UPDATE board
SET board_view_cnt = board_view_cnt + 1
WHERE board_no = #{no}

UPDATE board
SET board_title = #{boardTitle}, board_content = #{boardContent}
WHERE board_no = #{boardNo};

UPDATE files
SET file_name = #{fileName}, file_path = #{filePath}, file_system_name =
#{fileSystemName}
WHERE board_no = #{boardNo} AND file_no = #{fileNo};
